var o=[{title:`Tipos comuns de caminhada com carga`,text:`Na caminhada do agricultor (farmer’s carry), segura um peso em cada mão. Na caminhada unilateral (suitcase carry), segura um peso de um só lado, por isso o tronco tem de resistir à inclinação lateral. Na caminhada com a carga à frente, segura o peso junto ao peito, e na caminhada com a carga acima da cabeça exige-se mais estabilidade dos ombros e é preciso mais altura livre. Cada posição altera os músculos e a competência envolvidos.`},{title:`Técnica básica`,text:`Escolha uma carga que consiga segurar com firmeza durante todo o percurso, mantenha-se direito numa postura confortável e caminhe com passos deliberados. Mantenha o peso seguro, não se incline muito para o lado dele nem para o lado oposto e continue a respirar num percurso longo. Abrande ao virar e mantenha o caminho livre.`},{title:`Como dosear as caminhadas com carga`,text:`As caminhadas com carga contam-se por distância ou tempo em vez de repetições. Por exemplo, transporte dois halteres que consiga segurar com estabilidade durante 20–30 segundos, descanse e repita. Quando a pega e a postura se mantiverem iguais, acrescente um pouco de distância, tempo ou peso. Um peso maior não ajuda se tornar os passos apressados e irregulares.`},{title:`Espaço e segurança`,text:`Verifique se o percurso tem espaço livre suficiente no chão, uma superfície antiderrapante e nenhuma pessoa ou objeto no caminho. Pouse os pesos com controlo e não os deixe cair. Dispense as caminhadas com carga acima da cabeça sob um teto baixo ou quando não tiver a certeza do controlo dos ombros. Treine sempre as caminhadas unilaterais dos dois lados.`},{title:`Usar o TrainUp`,text:`As caminhadas com carga podem ocupar um lugar de força quando tem o equipamento e espaço para andar. O seu plano verifica o tamanho do espaço livre que definiu no Profile. Se as costas ou as mãos limitarem a carga na coluna ou o trabalho de pega que consegue suportar, adicione essa zona do corpo como limitação no Profile para que o plano possa deixar de fora os exercícios que não servem.`}];var s=[{label:`Biblioteca de exercícios da ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`NSCA: segurança e fundamentos do treino de resistência`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};